const PENCIL_TEXTURE_DATA = "data:image/jpeg;base64,";
const WATERMARK_DATA = "data:image/png;base64,";

export class oneLastImage extends plugin {
  constructor() {
    super({
      name: '卢浮宫生成器',
      dsc: '生成One Last Kiss风格的图片',
      event: 'message',
      priority: 500,
      rule: [
        {
          reg: /^#卢浮宫(帮助|help)$/i,
          fnc: 'showHelp'
        },
        {
          reg: '^#卢浮宫',
          fnc: 'generateLouvreImage'
        }
      ]
    });
  }
  
  /**
   * 显示插件帮助信息
   */
  async showHelp(e) {
    const helpMsg = `======= 卢浮宫生成器 =======
可通过添加不同参数，自由组合生成效果。

【基础用法】
 ▸ #卢浮宫 + [图片]
 ▸ [回复图片] + #卢浮宫
 ▸ #卢浮宫 @某人

【可用参数】 (可任意组合)
 ▸ 线条风格 (默认: 一般)
   精细, 稍粗, 超粗, 极粗, 浮雕, 线稿
   
 ▸ 开关选项 (兼容大小写, 如"关kiss")
   开/关降噪 (默认: 开)
   开/关Kiss (默认: 开)
   开/关水印 (默认: 开)
   开/关初回 (默认: 关)
   
 ▸ 数值滑块
   线迹[数值] (范围80-126, 默认: 118)
   调子[数值] (范围20-200, 默认: 108)

【使用示例】
 ▸ #卢浮宫 关水印
 ▸ #卢浮宫 超粗 线迹90
 ▸ #卢浮宫 开初回 关降噪 调子190
    `;
    await e.reply(helpMsg);
    return true;
  }

  /**
   * 主函数，处理图片生成请求
   */
  async generateLouvreImage(e) {
    if (isRunning) {
      e.reply('当前有任务正在生成，请稍后再试');
      return true;
    }
    isRunning = true;

    try {
      let imageUrl = '';

      // 使用新的、更强大的方法获取引用消息中的图片
      const repliedImages = await this.takeSourceMsg(e, { img: true });
      if (repliedImages) {
        // takeSourceMsg 返回的是一个图片URL数组，我们只取第一张
        imageUrl = repliedImages[0];
      }

      if (!imageUrl && e.img?.length > 0) {
        imageUrl = e.img[0].url || e.img[0];
      }

      if (!imageUrl && e.at) {
        imageUrl = `https://q1.qlogo.cn/g?b=qq&nk=${e.at}&s=640`;
      }

      if (!imageUrl) {
        e.reply('请发送 #卢浮宫+[图片]，或引用图片回复#卢浮宫，或 #卢浮宫@某人');
        isRunning = false;
        return true;
      }

      const options = this.parseOptions(e.msg);
      logger.info(`[卢浮宫生成器] 应用参数: ${JSON.stringify(options)}`);

      const waitingMsg = await e.reply('图片收到，正在送往卢浮宫加工...', true);
      const base64Image = await this.render(imageUrl, options);
      
      if (waitingMsg?.message_id && e.bot.recallMsg) {
         try {
           await e.bot.recallMsg(e.group_id || e.user_id, waitingMsg.message_id);
         } catch (err) { /* 忽略撤回失败 */ }
      }

      if (base64Image) {
        await e.reply(segment.image(base64Image));
      } else {
        await e.reply('生成失败了，可能是图片下载或本地渲染失败，请稍后再试 T_T');
      }

    } catch (error) {
      logger.error('[卢浮宫生成器] 插件执行出错:', error);
      await e.reply('插件出错了，请联系机器人管理员查看后台日志');
    } finally {
      isRunning = false;
    }
    return true;
  }

  /**
   * 解析用户输入的参数, 未指定的参数将保持默认值
   */
  parseOptions(msg) {
    const options = {
      style: '一般',
      lineWeight: 118,
      toneCount: 108,
      denoise: true,
      kiss: true,
      watermark: true,
      firstEdition: false,
    };
    if (!msg) return options;
    const cleanMsg = msg.replace(/^#卢浮宫/, '').trim();
    const lowerCaseMsg = cleanMsg.toLowerCase();

    const styles = ['精细', '稍粗', '超粗', '极粗', '浮雕', '线稿'];
    for (const style of styles) {
      if (cleanMsg.includes(style)) {
        options.style = style;
        break;
      }
    }

    const lineMatch = cleanMsg.match(/线迹\s*(\d+)/);
    if (lineMatch?.[1]) {
      options.lineWeight = Math.max(80, Math.min(126, parseInt(lineMatch[1])));
    }

    const toneMatch = cleanMsg.match(/调子\s*(\d+)/);
    if (toneMatch?.[1]) {
      options.toneCount = Math.max(20, Math.min(200, parseInt(toneMatch[1])));
    }
    
    const toggles = [
      { key: 'denoise', name: '降噪' },
      { key: 'kiss', name: 'Kiss' },
      { key: 'watermark', name: '水印' },
      { key: 'firstEdition', name: '初回' }
    ];
    for (const toggle of toggles) {
      const lowerCaseName = toggle.name.toLowerCase();
      if (lowerCaseMsg.includes('开' + lowerCaseName)) {
        options[toggle.key] = true;
      } else if (lowerCaseMsg.includes('关' + lowerCaseName)) {
        options[toggle.key] = false;
      }
    }

    return options;
  }

  /**
   * 使用 Puppeteer 的本地 Canvas 进行渲染
   */
  async render(imageUrl, options) {
    let browser = null;
    let ownsBrowser = false;

    try {
      if (typeof puppeteer.browserInit === 'function') {
        browser = await puppeteer.browserInit();
      } else if (puppeteer.browser?.newPage) {
        browser = puppeteer.browser;
      } else {
        const puppeteerModule = await import('puppeteer');
        const puppeteerCore = puppeteerModule.default || puppeteerModule;
        logger.warn('[卢浮宫生成器] 当前 Yunzai 未暴露 browserInit，使用独立 Puppeteer 浏览器');
        browser = await puppeteerCore.launch({
          headless: 'new',
          args: ['--disable-gpu', '--disable-setuid-sandbox', '--no-sandbox', '--no-zygote'],
        });
        ownsBrowser = true;
      }
    } catch (error) {
      logger.error('[卢浮宫生成器] Puppeteer 初始化失败:', error);
      return null;
    }

    if (!browser?.newPage) {
      logger.error('[卢浮宫生成器] 没有可用的 Puppeteer 浏览器实例');
      return null;
    }

    const page = await browser.newPage();

    try {
      const response = await fetch(imageUrl);
      if (!response.ok) throw new Error(`下载图片失败: ${response.statusText}`);

      const buffer = Buffer.from(await response.arrayBuffer());
      const contentType =
        response.headers.get('content-type')?.split(';', 1)[0] || 'image/jpeg';
      const imageData = `data:${contentType};base64,${buffer.toString('base64')}`;
      const config = {
        zoom: 1,
        light: 0,
        shadeLimit: options.toneCount,
        shadeLight: 80,
        shade: true,
        kuma: options.kiss,
        hajimei: options.firstEdition,
        watermark: options.watermark,
        convoluteName: options.style,
        convolute1Diff: true,
        convoluteName2: null,
        Convolutes: {
          精细: new Array(25).fill(1 / 25),
          一般: new Array(49).fill(1 / 49),
          稍粗: new Array(81).fill(1 / 81),
          超粗: new Array(121).fill(1 / 121),
          极粗: new Array(169).fill(1 / 169),
          浮雕: [1, 1, 1, 1, 1, -1, -1, -1, -1],
          线稿: null,
        },
        lightCut: 128,
        darkCut: options.lineWeight,
        denoise: options.denoise,
      };

      const runnerScript = [
        'window.__louvreDone = false;',
        'window.__louvreError = null;',
        `const inputData = ${JSON.stringify(imageData)};`,
        `const renderConfig = ${JSON.stringify(config)};`,
        `const pencilTextureData = ${JSON.stringify(PENCIL_TEXTURE_DATA)};`,
        `const watermarkData = ${JSON.stringify(WATERMARK_DATA)};`,
        'const loadLocalImage = src => new Promise((resolve, reject) => {',
        '  const image = new Image();',
        '  image.onload = () => resolve(image);',
        '  image.onerror = reject;',
        '  image.src = src;',
        '});',
        '(async () => {',
        '  try {',
        '    const [inputImage, pencilImage, watermarkImage] = await Promise.all([',
        '      loadLocalImage(inputData),',
        '      loadLocalImage(pencilTextureData),',
        '      loadLocalImage(watermarkData),',
        '    ]);',
        '    pencilTextureEl = pencilImage;',
        '    watermarkImageEl = watermarkImage;',
        '    const outputCanvas = document.createElement("canvas");',
        '    await louvre({ img: inputImage, outputCanvas, config: renderConfig });',
        '    window.__louvreResult = outputCanvas.toDataURL("image/jpeg", 0.9);',
        '  } catch (error) {',
        '    window.__louvreError = error?.stack || String(error);',
        '  } finally {',
        '    window.__louvreDone = true;',
        '  }',
        '})();',
      ].join('\n');

      await page.setViewport({ width: 1280, height: 800 });
      await page.setContent(
        '<!doctype html><html><head><meta charset="utf-8"></head><body>' +
          `<script>${LOCAL_LOUVRE_SCRIPT}</script>` +
          `<script>${runnerScript}</script>` +
          '</body></html>',
        { waitUntil: 'load', timeout: 60000 },
      );

      await page.waitForFunction(() => window.__louvreDone, { timeout: 60000 });
      const result = await page.evaluate(() => {
        if (window.__louvreError) throw new Error(window.__louvreError);
        return window.__louvreResult || null;
      });
      if (!result) throw new Error('本地 Canvas 没有生成输出图片');
      return result;
    } catch (error) {
      logger.error('[卢浮宫生成器] 本地 Canvas 渲染失败:', error);
      return null;
    } finally {
      await page.close().catch(() => {});
      if (ownsBrowser) await browser.close().catch(() => {});
    }
  }

  async takeSourceMsg(e, { img } = {}) {
    let source = null;
    if (typeof e.getReply === 'function') {
      source = await e.getReply();
    } else if (e.source) {
      if (e.group?.getChatHistory) {
        source = (await e.group.getChatHistory(e.source.seq, 1))?.pop();
      } else if (e.friend?.getChatHistory) {
        source = (await e.friend.getChatHistory(e.source.time, 1))?.pop();
      }
    }
    if (!source) return false;
    if (img) {
      const imgArr = source.message?.filter(s => s.type === "image" && s.url).map(s => s.url) || [];
      return imgArr.length > 0 ? imgArr : false;
    }
    return source;
  } 
}
